// Characterization tests: pin the current client-visible behaviour of the HTTP API,
// including quirks (marked QUIRK) so a restructuring can't change them unnoticed.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 0.5, D: 33.33, E: 101 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})
const create = async (items) => {
  const res = await post({ items })
  return { res, body: await res.json() }
}

test('POST /orders creates an order: 201, json, id/items/total', async () => {
  const { res, body } = await create([{ sku: 'A', qty: 2 }])
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body.items, [{ sku: 'A', qty: 2 }])
  assert.equal(body.total, 20)
})

test('total sums price * qty across items', async () => {
  const { body } = await create([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 3 }])
  assert.equal(body.total, 95)
})

test('no discount at exactly 100', async () => {
  const { body } = await create([{ sku: 'A', qty: 10 }])
  assert.equal(body.total, 100)
})

test('10% discount when total is over 100', async () => {
  const { body } = await create([{ sku: 'A', qty: 11 }])
  assert.equal(body.total, 99)
})

test('total is floored to an integer (after discount)', async () => {
  assert.equal((await create([{ sku: 'E', qty: 1 }])).body.total, 90) // 90.9
  assert.equal((await create([{ sku: 'D', qty: 1 }])).body.total, 33) // 33.33
  assert.equal((await create([{ sku: 'C', qty: 1 }])).body.total, 0) // 0.5
})

test('ids are sequential strings', async () => {
  const a = (await create([{ sku: 'A', qty: 1 }])).body.id
  const b = (await create([{ sku: 'A', qty: 1 }])).body.id
  assert.equal(Number(b), Number(a) + 1)
})

test('items are echoed back unchanged, including extra fields', async () => {
  const items = [{ sku: 'A', qty: 1, note: 'x' }]
  assert.deepEqual((await create(items)).body.items, items)
})

test('GET /orders/:id returns the created order', async () => {
  const { body: created } = await create([{ sku: 'B', qty: 1 }])
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order: QUIRK status 200 with error body', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('POST validation: 400 { error: "items required" }', async () => {
  const cases = [
    JSON.stringify({}),
    JSON.stringify({ items: [] }),
    JSON.stringify({ items: 'nope' }),
    JSON.stringify({ items: null }),
    '{not json',
    '', // empty body parses as {}
  ]
  for (const raw of cases) {
    const res = await post(undefined, raw)
    assert.equal(res.status, 400, raw)
    assert.deepEqual(await res.json(), { error: 'items required' }, raw)
  }
})

test('rejected orders are not stored', async () => {
  const before = await (await fetch(`${base}/orders/next-probe`)).json()
  assert.deepEqual(before, { error: 'not found' })
  const a = (await create([{ sku: 'A', qty: 1 }])).body.id
  await post({ items: [] })
  const b = (await create([{ sku: 'A', qty: 1 }])).body.id
  assert.equal(Number(b), Number(a) + 1) // failed POST doesn't consume an id
})

test('unknown routes and methods: 404 { error: "no route" }', async () => {
  const probes = [
    ['GET', '/'],
    ['GET', '/orders'],
    ['GET', '/orders/1/extra'],
    ['PUT', '/orders'],
    ['DELETE', '/orders/1'],
    ['POST', '/orders/1'],
    ['GET', '/other'],
  ]
  for (const [method, path] of probes) {
    const res = await fetch(base + path, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' }, `${method} ${path}`)
  }
})

test('query strings are ignored when routing', async () => {
  const res = await fetch(`${base}/orders?x=1`, {
    method: 'POST',
    body: JSON.stringify({ items: [{ sku: 'A', qty: 1 }] }),
  })
  assert.equal(res.status, 201)
})
EOF
